@startuml

class Cinema {
  + Name : string
  + Town : string
}

class Theatre {
  + Number : int
}

class Movie {
  + Title : string
}

class MovieCopy {
  + Id : int
}

class Show {
  + StartTime : datetime
  + EndTime : datetime
  + publish()
  + cancelShow()
}

class Seat {
  + SeatNumber : int
}

class OnlineReservation {
  + ReservationTime : datetime
  + cancelReservation()
}

class AlternativeOffer {
  + expire()
  + accept()
  + decline()
}

class FreeTicket {
  + SentToHome : boolean
}

class Ticket {
  + Price : float
}

class Customer {
  + Name : string
}

Cinema "1" -- "0..*" Theatre
